import random, json, sys, itertools
sys.path.insert(0,'/workspace/submission')
import analyze as A
sys.path.insert(0,'/workspace/dev')
import brute as B

NAMES=['A','B','C','D','E']

def rand_name(i):
    return NAMES[i]

def find_path(edges, s, t, nodes):
    # DFS simple directed path
    adj={n:[] for n in nodes}
    for e in edges:
        adj[e['source']].append((e['target'],e['id']))
    res=[]
    def dfs(cur,path,visited):
        if cur==t:
            res.append(list(path)); return True
        for (nx,eid) in adj[cur]:
            if nx not in visited:
                visited.add(nx); path.append(eid)
                if dfs(nx,path,visited): 
                    pass
                path.pop(); visited.remove(nx)
        return False
    dfs(s,[],{s})
    if not res: return None
    return random.choice(res)

def gen(seed):
    rnd=random.Random(seed)
    nn=rnd.randint(2,4)
    nodes=NAMES[:nn]
    ne=rnd.randint(0,6)
    edges=[]
    for i in range(ne):
        s,t=rnd.sample(nodes,2)
        edges.append({'id':'e%d'%i,'source':s,'target':t,'capacity':rnd.choice([1,2,3,5,100])})
    # commodities
    nc=rnd.randint(0,2)
    comms=[]
    used=set()
    for i in range(nc):
        tries=0
        while tries<30:
            s,t=rnd.sample(nodes,2)
            if (s,t) in used: 
                tries+=1; continue
            p=find_path(edges,s,t,nodes)
            if p is None:
                tries+=1;continue
            break
        else:
            continue
        used.add((s,t))
        nr=rnd.randint(1,2)
        routes=[]
        for k in range(nr):
            if k==0:
                pp=p
            else:
                pp=find_path(edges,s,t,nodes)
                if pp is None: pp=p
            w=rnd.randint(1,2)
            routes.append({'edges':pp,'weight':w})
        # ensure weight sum<=8
        if sum(r['weight'] for r in routes)>8:
            for r in routes: r['weight']=1
        comms.append({'id':'c%d'%i,'source':s,'target':t,'routes':routes})
    # domains
    nd=rnd.randint(0,2)
    domains=['d%d'%i for i in range(nd)]
    mf=rnd.randint(0,max(0,nd))
    ns=rnd.randint(1,2)
    snaps=[]
    for si in range(ns):
        bounds=[[0,rnd.randint(0,3)] for _ in range(len(comms))]
        ctrl=[rnd.randint(0,3) for _ in range(len(comms))]
        tol=rnd.choice([0,1])
        obs=[]
        # add some observations
        no=rnd.randint(0,4)
        oid=0
        for _ in range(no):
            metric=rnd.choice(['demand','link','ingress','egress'])
            if metric=='demand' and comms:
                target=rnd.choice(comms)['id']
            elif metric=='link' and edges:
                target=rnd.choice(edges)['id']
            else:
                metric=rnd.choice(['ingress','egress'])
                target=rnd.choice(nodes)
            lo=rnd.randint(-1,4); hi=lo+rnd.randint(0,2)
            dom=rnd.choice(domains+[None]) if domains else None
            obs.append({'id':'o%d'%oid,'metric':metric,'target':target,'lower':lo,'upper':hi,'domain':dom})
            oid+=1
        snaps.append({'id':'s%d'%si,'bounds':bounds,'controller':ctrl,'tolerance':tol,'observations':obs})
    req={'id':'r%d'%seed,'version':1,'nodes':nodes,'edges':edges,'commodities':comms,
         'domains':domains,'max_faults':mf,'snapshots':snaps}
    return req

def run(seed):
    req=gen(seed)
    try:
        norm=A.validate(req)
    except Exception as e:
        return ('invalid',seed,str(e),req)
    try:
        got=A.solve(norm)
    except Exception as e:
        import traceback; traceback.print_exc()
        return ('solvererr',seed,str(e),req)
    exp=B.brute(req)
    # compare
    ok=True
    msgs=[]
    if got.get('status')!=exp['status']: ok=False;msgs.append(('status',got.get('status'),exp['status']))
    if got.get('status')!='infeasible':
        if got['min_faults']!=exp['min_faults']: ok=False;msgs.append(('minf',got['min_faults'],exp['min_faults']))
        if sorted(got['faults']['forced'])!=sorted(exp['faults']['forced']): ok=False;msgs.append(('forced',got['faults']['forced'],exp['faults']['forced']))
        if sorted(got['faults']['possible'])!=sorted(exp['faults']['possible']): ok=False;msgs.append(('poss',got['faults']['possible'],exp['faults']['possible']))
        for s in range(len(exp['snapshots'])):
            gs=got['snapshots'][s]; es=exp['snapshots'][s]
            if gs['demands']!=es['demands']: ok=False;msgs.append(('dem',s,gs['demands'],es['demands']))
            if gs['links']!=es['links']: ok=False;msgs.append(('link',s,gs['links'],es['links']))
            if gs['verdict']!=es['verdict']: ok=False;msgs.append(('verd',s,gs['verdict'],es['verdict']))
    if not ok:
        return ('FAIL',seed,msgs,req)
    return ('ok',seed)

if __name__=='__main__':
    nf=0
    N=int(sys.argv[1]) if len(sys.argv)>1 else 200
    for seed in range(N):
        r=run(seed)
        if r[0] not in ('ok',):
            if r[0]=='invalid':
                continue
            print('SEED',seed,r[0], r[2] if r[0]!='FAIL' else '')
            if r[0]=='FAIL':
                for m in r[2]: print('   ',m)
                print('   REQ', json.dumps(r[3]))
            nf+=1
            if nf>10: break
    print('done, failures',nf)
